import org.jetbrains.kotlin.gradle.dsl.JvmTarget

plugins {
    id("com.android.application")

    id("org.jetbrains.kotlin.plugin.compose")
    id("org.jetbrains.kotlin.plugin.serialization")
    id("com.google.devtools.ksp")
}

android {
    namespace = "com.lawsearch.app"
    // RuntimeShader（AGSL）玻璃效果在 API 33+ 才完整；编译用 37
    compileSdk = 37

    defaultConfig {
        applicationId = "com.lawsearch.app.glass"
        minSdk = 26
        targetSdk = 37
        versionCode = 11
        versionName = "1.1.2RC"

        // Built-in law data: assets/laws/*.json.gz (generated by tools/bundle_laws.py).
        // Set to false to ship without bundled data (first launch then needs network).
        buildConfigField("String", "BUNDLED_LAWS_DIR", "\"laws\"")
        buildConfigField("boolean", "BUNDLE_LAWS", "true")
        // 测试版标记：为 true 时界面显示测试版横幅与提示
        buildConfigField("boolean", "IS_RC", "false")
    }

    // 测试版 flavor：applicationId 加 .rc 后缀，可与正式版共存
    flavorDimensions += "channel"
    productFlavors {
        create("stable") {
            dimension = "channel"
            applicationId = "com.lawsearch.app.glass"
        }
        create("rc") {
            dimension = "channel"
            applicationId = "com.lawsearch.app.glass.rc"
            versionNameSuffix = "RC"
            buildConfigField("boolean", "IS_RC", "true")
        }
    }

    // Debug signing uses a workspace-local keystore (generated by make_keystore.py),
    // because ~/.android is not writable in this environment.
    signingConfigs {
        create("workspaceDebug") {
            storeFile = rootProject.file(".tools/keystore/debug.keystore")
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
    }

    buildTypes {
        debug {
            isMinifyEnabled = false
            signingConfig = signingConfigs.getByName("workspaceDebug")
        }
        release {
            // 开启 R8 代码压缩 + 资源压缩：
            // debug 包光 dex 就 19 MB（占比 41%），release 开混淆后通常能砍掉一半以上。
            isMinifyEnabled = true
            isShrinkResources = true
            // 用工作区 keystore 签名，否则 AGP 只产出 *-unsigned.apk，无法安装验证。
            // 正式发布时换成自己的正式 keystore。
            signingConfig = signingConfigs.getByName("workspaceDebug")
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlin {
        compilerOptions {
            jvmTarget.set(JvmTarget.JVM_17)
        }
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    packaging {
        resources {
            excludes += setOf("META-INF/DEPENDENCIES", "META-INF/LICENSE*", "META-INF/NOTICE*")
        }
    }

    testOptions {
        unitTests {
            isIncludeAndroidResources = true
            isReturnDefaultValues = true
        }
    }

    ksp {
        arg("room.schemaLocation", "$projectDir/schemas")
    }

    tasks.withType<Test>().configureEach {
        // Robolectric needs a writable home plus a locally cached android-all jar;
        // neither ~/.robolectric nor ~/.m2 is writable here, so the jar is pre-downloaded
        // into .tools/robolectric/jars15 (see tools/fetch_android_all.py).
        val roboHome = rootProject.file(".tools/robolectric")
        // Robolectric 4.14.1 的 ShadowPausedMessageQueue 与 SDK 35 的 MessageQueue 不兼容（mLast 字段已删），
        // 测试统一跑在 SDK 33 的 android-all 上。
        val jarDir = File(roboHome, "jars13").apply { mkdirs() }
        val jar = File(jarDir, "android-all-instrumented-13-robolectric-9030017-i7.jar")
        if (jar.exists()) {
            systemProperty("robolectric.offline", "true")
            systemProperty("robolectric.dependency.dir", jarDir.absolutePath)
        }
        systemProperty("user.home", roboHome.absolutePath)
        systemProperty("java.io.tmpdir", File(roboHome, "tmp").apply { mkdirs() }.absolutePath)
        // sqlite4java 默认会解压 .dll 到临时目录（本机沙箱不允许）；Robolectric 的
        // "native" SQLite 走纯 Java 实现即可满足 FTS5 测试
        systemProperty("sqlite4java.library.path", File(roboHome, "libs").apply { mkdirs() }.absolutePath)
        // Robolectric 的 SQLite 原生库需要可写目录：把 sandbox 的 tmp 指到工作区
        // Robolectric 4.14 默认用原生 SQLite（sqlite4java），需要把 .dll 解压到临时目录；
        // 本机沙箱不允许创建随机子目录，因此改用纯 Java 的 legacy 模式。
        jvmArgs("-Drobolectric.sqlite.mode=LEGACY")
        jvmArgs("-Djava.io.tmpdir=" + File(roboHome, "tmp").apply { mkdirs() }.absolutePath)
        jvmArgs("-Dsqlite4java.library.path=" + File(roboHome, "libs").apply { mkdirs() }.absolutePath)
        systemProperty("samples.dir", rootProject.file("../laws").absolutePath)
        // 强制每次测试都在新的 JVM 里跑（本机出现过旧测试 worker 复用陈旧类的情况）
        forkEvery = 1
        setForkEvery(1)
        // 本机观察到的异常：Kotlin 增量编译偶尔复用过期的 .class（源码正确但字节码是旧的）。
        // 测试任务先强制全量重编，避免"改代码但测试结果不变"的假象。
        // 引入 flavor 后任务名变成 compile{Flavor}DebugKotlin，这里按实际 flavor 动态取。
        dependsOn("compile${name.removePrefix("test").removeSuffix("UnitTest")}Kotlin")
        dependsOn("ksp${name.removePrefix("test").removeSuffix("UnitTest")}Kotlin")
        systemProperty("jdk.attach.allowAttachSelf", "true")
        // 在线测试开关：gradle -Ponline=1 或环境变量 LAWSEARCH_ONLINE=1
        val online = (findProperty("online")?.toString() == "1") ||
            System.getenv("LAWSEARCH_ONLINE") == "1"
        if (online) {
            systemProperty("LAWSEARCH_ONLINE", "1")
            environment("LAWSEARCH_ONLINE", "1")
        }
        maxHeapSize = "2g"
    }
}

dependencies {
    implementation("io.github.kyant0:backdrop:2.0.1")
    // backdrop 的几何形状（Capsule / RoundedRectangle 带连续曲率圆角）
    implementation("io.github.kyant0:shapes:1.2.1")
    // 历史上被传递依赖抬到过 androidx.core:1.19.0（要求 AGP 9.1+）；
    // 我们只需要 core 的基础 API，继续钉在 1.15.0 保证工具链稳定。
    // forceCoreDowngrade
    implementation("androidx.core:core-ktx:1.15.0")
    implementation("androidx.activity:activity-compose:1.9.3")
    implementation("androidx.lifecycle:lifecycle-runtime-ktx:2.8.7")
    implementation("androidx.lifecycle:lifecycle-viewmodel-compose:2.8.7")
    implementation("androidx.lifecycle:lifecycle-runtime-compose:2.8.7")

    val composeBom = platform("androidx.compose:compose-bom:2026.09.00")
    implementation(composeBom)
    androidTestImplementation(composeBom)
    implementation("androidx.compose.ui:ui")
    implementation("androidx.compose.ui:ui-graphics")
    implementation("androidx.compose.foundation:foundation")
    implementation("androidx.compose.animation:animation")
    implementation("androidx.compose.material3:material3")
    implementation("androidx.compose.material:material-icons-core")
    implementation("androidx.compose.material:material-icons-extended")

    implementation("androidx.navigation:navigation-compose:2.8.9")
    // 注：dev.chrisbanes.haze 已移除。玻璃效果统一走上面的 kyant0:backdrop，
    // 全项目已无任何 dev.chrisbanes.haze 引用（TabBar/LiquidGlass/TabPager 均已迁移）。

    implementation("androidx.room:room-runtime:2.7.1")
    implementation("androidx.room:room-ktx:2.7.1")
    ksp("androidx.room:room-compiler:2.7.1")

    implementation("androidx.work:work-runtime-ktx:2.9.1")

    implementation("com.squareup.okhttp3:okhttp:4.12.0")
    implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.8.0")

    testImplementation("junit:junit:4.13.2")
    testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.9.0")
    testImplementation("org.xerial:sqlite-jdbc:3.46.1.0")
    testImplementation("org.robolectric:robolectric:4.14.1")
    testImplementation("androidx.test:core:1.6.1")
    testImplementation("androidx.test.ext:junit:1.2.1")
}

// 强制把 androidx.core 系列钉在 1.15.0，避免被其它库的传递依赖抬到 1.19.0
configurations.all {
    resolutionStrategy {
        force("androidx.core:core:1.15.0")
        force("androidx.core:core-ktx:1.15.0")
    }
}
